        AND category_name like concat('%', #{categoryName}, '%')


        AND status = #{status}


order by parent_id, order_num, category_id

WITH RECURSIVE category_tree AS (
    SELECT category_id
    FROM lib_category
    WHERE category_id = #{categoryId}
    UNION DISTINCT
    SELECT child.category_id
    FROM lib_category child
    JOIN category_tree parent ON child.parent_id = parent.category_id
)
SELECT COUNT(*) FROM category_tree WHERE category_id = #{newParentId}
